mkdir -p ../clone-work && cat > ../clone-work/conc.ts <<'EOF'
import { Hono } from '../clone/src/hono'
const app = new Hono()
app.post('/c', async (c) => {
  try {
    const [pb, fd] = await Promise.all([c.req.parseBody(), c.req.formData()])
    return c.json({ pb, fd: [...fd.keys()] })
  } catch (e: any) { return c.text('ERR ' + e.message, 500) }
})
for (const ct of ['multipart', 'urlencoded']) {
  let body: any
  if (ct === 'multipart') { body = new FormData(); body.append('foo', 'bar') } else body = new URLSearchParams({ foo: 'bar' })
  const r = await app.request('/c', { method: 'POST', body })
  console.log(ct, r.status, await r.text())
}
EOF
./node_modules/.bin/esbuild ../clone-work/conc.ts --bundle --platform=node --format=esm --outfile=../clone-work/conc.mjs --log-level=warning && node ../clone-work/conc.mjs; git stash list | head -1; git status --short | head

